using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36.R104;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying || EditorSceneManager.GetActiveScene().isDirty)
                throw new Exception("Clean Edit needed");
            if (!EditorSceneManager.GetActiveScene().path.EndsWith("r104.unity"))
                EditorSceneManager.OpenScene("Assets/Scenes/JourneyPresentation_v48_r104.unity");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!s)
                throw new Exception("r104 session missing");
            var text = "scene=" + s.gameObject.scene.path + " clean=" + !s.gameObject.scene.isDirty + "\n";
            foreach (var a in s.GetComponentsInChildren<InvestigationActor>(true))
                text += "Actor " + a.name + " parent=" + a.transform.parent.name + " pos=" + a.transform.localPosition + " scale=" + a.transform.localScale + " puppet=" + a.puppet + "\n";
            foreach (var x in s.GetComponentsInChildren<InvestigationInteractable>(true))
                text += "Interact " + x.name + " id=" + x.evidenceId + " action=" + x.action + "\n";
            text += "clipCamera=" + s.clipCamera.transform.localPosition + " fov=" + s.clipCamera.fieldOfView + " actor=" + s.repairEventActor.name + "\n";
            File.WriteAllText("Test/KetQua/investigation_r104/scene-inventory.txt", text);
            r.Log(text);
        }
    }
}

